/**
 * Paper Cannon — case study.
 *
 * Faithful port of the standalone v3 design comp
 * (paper-cannon-case-study-v3.html). The comp is a complete editorial layout
 * with its own palette/typography; we render it inside the site shell
 * (SiteChrome header/footer) with every style SCOPED under a `.pc` wrapper so
 * none of its global element rules (body/h1/p/.note/.col/...) leak into the
 * rest of the portfolio. The comp's own <header>/<footer> and reveal <script>
 * are dropped — the site provides chrome, and content renders statically
 * visible without the IntersectionObserver. Its nav/crumb links are rewritten
 * to internal routes. Generated markup + scoped CSS are embedded as strings to
 * preserve the comp's 14 pixel-art SVG sprites byte-for-byte.
 */

const STYLES = ".pc{\n    --paper:#FAF7F1; --paper-2:#F3EEE3; --card:#FCFAF5;\n    --ink:#2A231B; --ink-soft:#4A4038; --muted:#6E665B;\n    --clay:#BC6349; --green:#2E7D57; --rule:#E4DDCF;\n    --dark:#16171E; --dark-2:#1E2029; --dark-ink:#ECE7DD; --dark-mut:#9A98A4;\n    --amber:#D7A24A; --cyan:#4FB6CE; --grn:#54B583; --red:#E06B57; --steel:#5C7C9E; --plum:#8A6A96;\n    --serif:\"Source Serif 4\",Georgia,serif;\n    --sans:\"Source Sans 3\",-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;\n    --mono:\"IBM Plex Mono\",ui-monospace,SFMono-Regular,Menlo,monospace;\n  }\n.pc, .pc *{box-sizing:border-box;}\n.pc{scroll-behavior:smooth;}\n.pc{margin:0; background:var(--paper); color:var(--ink);\n    font-family:var(--sans); font-size:18px; line-height:1.6;\n    -webkit-font-smoothing:antialiased; text-rendering:optimizeLegibility;}\n.pc a{color:inherit;}\n.pc .wrap{max-width:1080px; margin:0 auto; padding:0 32px;}\n.pc .measure{max-width:720px;}\n.pc .top{position:sticky; top:0; z-index:20; background:rgba(250,247,241,.86);\n    backdrop-filter:saturate(1.1) blur(8px); border-bottom:1px solid var(--rule);}\n.pc .top__in{display:flex; align-items:baseline; justify-content:space-between;\n    padding:14px 32px; max-width:1080px; margin:0 auto;}\n.pc .brand{font-family:var(--serif); font-weight:700; font-size:20px; letter-spacing:-.01em;}\n.pc .brand span{font-family:var(--mono); font-weight:500; font-size:10.5px;\n    letter-spacing:.16em; color:var(--clay); margin-left:10px; text-transform:uppercase;}\n.pc .nav{font-family:var(--mono); font-size:12px;}\n.pc .nav a{color:var(--muted); text-decoration:none; margin-left:22px;}\n.pc .nav a:hover{color:var(--ink);}\n.pc .nav a.here{color:var(--ink);}\n@media(max-width:640px){.pc .nav{display:none;}\n}\n.pc .eyebrow{font-family:var(--mono); font-size:12px; font-weight:500; letter-spacing:.15em;\n    text-transform:uppercase; color:var(--clay); margin:0 0 18px;}\n.pc h1{font-family:var(--serif); font-weight:700; font-size:clamp(46px,8.5vw,84px);\n    line-height:.99; letter-spacing:-.02em; margin:.12em 0 .1em;}\n.pc h2{font-family:var(--serif); font-weight:600; font-size:clamp(27px,3.6vw,38px);\n    line-height:1.12; letter-spacing:-.015em; margin:0 0 .55em; max-width:20ch;}\n.pc h3{font-family:var(--serif); font-weight:600; font-size:22px; line-height:1.25;\n    letter-spacing:-.01em; margin:0 0 .35em;}\n.pc p{margin:0 0 1.15em;}\n.pc .lead{font-size:clamp(20px,2.4vw,24px); line-height:1.5; color:var(--ink-soft);}\n.pc .sub{font-family:var(--mono); font-size:14px; color:var(--muted);}\n.pc section{padding:70px 0;}\n.pc .crumb{font-family:var(--mono); font-size:12.5px; color:var(--muted);\n    text-decoration:none; display:inline-block; margin-bottom:26px;}\n.pc .crumb:hover{color:var(--clay);}\n.pc .sp{height:54px; width:auto; display:block; image-rendering:pixelated;}\n.pc .sp-sm{height:44px;}\n.pc .sp-lg{height:72px;}\n.pc .hero{padding-top:46px; padding-bottom:30px;}\n.pc .hero .sub{margin-bottom:26px; font-size:15px; max-width:62ch;}\n.pc .metastrip{font-family:var(--mono); font-size:12px; color:var(--muted); line-height:1.9;\n    letter-spacing:.02em; border-top:1px solid var(--rule); border-bottom:1px solid var(--rule);\n    padding:12px 0; margin:0 0 30px; display:flex; flex-wrap:wrap; gap:6px 26px;}\n.pc .metastrip b{color:var(--ink); font-weight:600;}\n.pc .hero-hook{margin-top:30px;}\n.pc figure{margin:0;}\n.pc .diorama{position:relative; border:1px solid var(--rule); border-radius:14px;\n    background:linear-gradient(180deg,#F1EADB 0%,#EFE7D6 62%,#E7DcC6 62.01%,#E4D8C0 100%);\n    padding:22px 24px 20px; overflow:hidden; box-shadow:0 1px 0 rgba(42,35,27,.03);}\n.pc .board{position:relative; height:74px; border:2px solid #C9B79A; border-radius:6px;\n    background:repeating-linear-gradient(45deg,#EFE3CC,#EFE3CC 8px,#EAD9BD 8px,#EAD9BD 16px);\n    margin-bottom:20px; display:flex; align-items:center; gap:10px; padding:0 14px;}\n.pc .board::before{content:\"BULLETIN\"; position:absolute; top:-9px; left:12px; background:var(--card);\n    font-family:var(--mono); font-size:9.5px; letter-spacing:.14em; color:var(--muted); padding:0 6px;}\n.pc .note{font-family:var(--mono); font-size:10.5px; line-height:1.35; color:#5A4E3A; background:#FFFDF4;\n    border:1px solid #DAC9A6; padding:6px 9px; border-radius:3px; transform:rotate(-1.4deg);\n    box-shadow:0 1px 2px rgba(0,0,0,.08);}\n.pc .note.b{transform:rotate(1.6deg);}\n.pc .note.c{transform:rotate(-.6deg);}\n.pc .timer{margin-left:auto; font-family:var(--mono); font-size:11px; color:#7A6C52;\n    border:1px solid #C9B79A; border-radius:4px; padding:4px 8px; background:#F6EEDD;}\n.pc .timer b{color:var(--clay);}\n.pc .floor{display:flex; align-items:flex-end; justify-content:space-between; gap:6px; flex-wrap:wrap;}\n.pc .fig{position:relative; display:flex; flex-direction:column; align-items:center; gap:5px; flex:1 1 0; min-width:60px;}\n.pc .fig .lbl{font-family:var(--mono); font-size:9.5px; letter-spacing:.03em; color:#6B5E48; white-space:nowrap;}\n.pc .fig.watch{flex:0 0 auto; margin-left:8px; padding-left:16px; border-left:1px dashed #C9B79A; opacity:.9;}\n.pc .fig.watch .lbl{color:var(--clay);}\n.pc .bub{position:absolute; top:-30px; font-family:var(--mono); font-size:10px; color:#7A2E1E;\n    background:#FBEAE4; border:1px solid #E7C3B8; border-radius:8px; padding:4px 8px; white-space:nowrap;\n    display:none;}\n.pc .bub.show{display:block;}\n.pc .bub::after{content:\"\"; position:absolute; bottom:-5px; left:16px; width:8px; height:8px;\n    background:#FBEAE4; border-right:1px solid #E7C3B8; border-bottom:1px solid #E7C3B8; transform:rotate(45deg);}\n.pc figcaption{font-family:var(--mono); font-size:12.5px; color:var(--muted); margin-top:14px; line-height:1.5;}\n.pc figcaption b{color:var(--ink); font-weight:500;}\n.pc .status{display:flex; flex-wrap:wrap; gap:8px; margin-top:26px;}\n.pc .chip{font-family:var(--mono); font-size:12px; padding:6px 12px; border-radius:999px;\n    border:1px solid var(--rule); background:var(--card); color:var(--ink-soft);}\n.pc .chip b{color:var(--green); font-weight:600;}\n.pc .chip.next b{color:var(--clay);}\n.pc .compare{display:grid; grid-template-columns:repeat(3,1fr); gap:16px; margin-top:34px;}\n@media(max-width:820px){.pc .compare{grid-template-columns:1fr;}\n}\n.pc .cmp{border:1px solid var(--rule); border-radius:12px; background:var(--card);\n    border-top:3px solid var(--cc,#999); padding:20px 22px 22px; display:flex; flex-direction:column;}\n.pc .cmp__h{font-family:var(--mono); font-size:11.5px; font-weight:600; letter-spacing:.11em;\n    text-transform:uppercase; color:var(--cc,#777); margin-bottom:10px;}\n.pc .cmp p{font-size:15px; line-height:1.5; color:var(--ink-soft); margin:0 0 16px; flex:1;}\n.pc .cmp__tag{font-family:var(--mono); font-size:11px; font-weight:500; letter-spacing:.06em;\n    text-transform:uppercase; align-self:flex-start; padding:3px 10px; border-radius:20px;\n    border:1px solid var(--rule); color:var(--muted); background:var(--paper-2);}\n.pc .c-bad{--cc:var(--red);}\n.pc .c-mid{--cc:var(--amber);}\n.pc .c-good{--cc:var(--green);}\n.pc .c-good .cmp__tag{background:#E7F0EA; color:var(--green); border-color:#CFE2D6;}\n.pc .dark{background:var(--dark); color:var(--dark-ink);}\n.pc .dark .eyebrow{color:var(--amber);}\n.pc .dark h2{color:var(--dark-ink);}\n.pc .dark .measure p{color:#CFCBD6;}\n.pc .thesis{font-family:var(--serif); font-weight:600; font-size:clamp(29px,4.6vw,50px);\n    line-height:1.07; letter-spacing:-.02em; margin:.1em 0 .55em; max-width:17ch;}\n.pc .thesis em{font-style:italic; color:#fff;}\n.pc .arch{display:flex; align-items:stretch; gap:0; margin:48px 0 18px; flex-wrap:nowrap;}\n.pc .io{flex:0 0 92px; display:flex; align-items:center; justify-content:center; text-align:center;\n    font-family:var(--mono); font-size:12px; letter-spacing:.04em; color:var(--dark-mut); line-height:1.5;}\n.pc .arw{flex:0 0 32px; align-self:center; text-align:center; color:#55565f; font-size:20px;}\n.pc .layer{flex:1 1 0; background:var(--dark-2); border:1px solid #2b2d38;\n    border-top:3px solid var(--ly,#666); border-radius:10px; padding:16px 15px 15px; min-width:0;}\n.pc .layer__tag{font-family:var(--mono); font-size:11.5px; font-weight:600; letter-spacing:.1em;\n    text-transform:uppercase; color:var(--ly,#aaa);}\n.pc .layer__role{font-size:12.5px; color:var(--dark-mut); margin:3px 0 12px; font-family:var(--mono);}\n.pc .layer__items{list-style:none; margin:0; padding:0;}\n.pc .layer__items li{font-size:14px; color:#DAD7E0; padding:7px 0; border-top:1px solid #262833; line-height:1.35;}\n.pc .layer__items li:first-child{border-top:0;}\n.pc .ly-stack{--ly:var(--grn);}\n.pc .ly-room{--ly:var(--amber);}\n.pc .ly-floor{--ly:var(--steel);}\n.pc .reindeer-band{margin-top:14px; border:1px dashed #3a3c48; border-radius:10px;\n    padding:13px 16px; display:flex; gap:12px; align-items:baseline;\n    font-family:var(--mono); font-size:12.5px; color:var(--dark-mut); line-height:1.5;}\n.pc .reindeer-band b{color:var(--red); font-weight:500; letter-spacing:.04em; text-transform:uppercase; font-size:11.5px; white-space:nowrap;}\n@media(max-width:760px){.pc .arch{flex-direction:column;}\n.pc .io{flex-basis:auto; padding:10px 0;}\n.pc .arw{flex-basis:auto; transform:rotate(90deg); padding:6px 0;}\n.pc .layer{width:100%;}\n}\n.pc .stats{display:grid; grid-template-columns:1fr 1fr; gap:18px; margin:40px 0 4px;}\n@media(max-width:600px){.pc .stats{grid-template-columns:1fr;}\n}\n.pc .stat{background:var(--dark-2); border:1px solid #2b2d38; border-radius:12px; padding:22px 24px;}\n.pc .stat__n{font-family:var(--serif); font-weight:700; font-size:clamp(40px,6vw,60px);\n    line-height:1; letter-spacing:-.02em; color:#fff;}\n.pc .stat__l{font-family:var(--mono); font-size:12.5px; color:var(--dark-mut); line-height:1.55; margin-top:12px;}\n.pc .stat__l b{color:#CFCBD6; font-weight:500;}\n.pc .rules{display:grid; grid-template-columns:1fr 1fr; gap:16px; margin-top:34px;}\n@media(max-width:720px){.pc .rules{grid-template-columns:1fr;}\n}\n.pc .rule-card{background:var(--dark-2); border:1px solid #2b2d38; border-radius:12px; padding:20px 22px;}\n.pc .rule-card h3{color:var(--dark-ink); font-size:19px;}\n.pc .rule-card p{font-size:15px; color:#CFCBD6; line-height:1.5; margin:0;}\n.pc .gates{display:flex; align-items:stretch; gap:0; margin-top:38px; flex-wrap:nowrap;}\n.pc .gph{flex:1 1 0; min-width:0; background:var(--card); border:1px solid var(--rule);\n    border-top:3px solid var(--pc,var(--clay)); border-radius:10px; padding:14px 15px 15px;}\n.pc .gph .n{font-family:var(--mono); font-size:11px; color:var(--muted); letter-spacing:.08em; text-transform:uppercase;}\n.pc .gph h4{font-family:var(--serif); font-weight:600; font-size:17px; margin:2px 0 5px; letter-spacing:-.01em;}\n.pc .gph p{font-size:13px; color:var(--ink-soft); line-height:1.4; margin:0;}\n.pc .g1{--pc:var(--steel);}\n.pc .g2{--pc:var(--clay);}\n.pc .g3{--pc:var(--green);}\n.pc .gate{flex:0 0 92px; align-self:stretch; display:flex; flex-direction:column;\n    align-items:center; justify-content:center; gap:8px; padding:0 6px; text-align:center;}\n.pc .gate__d{width:34px; height:34px; transform:rotate(45deg); border:2px solid var(--clay);\n    border-radius:6px; background:var(--paper-2); display:flex; align-items:center; justify-content:center;}\n.pc .gate__d span{transform:rotate(-45deg); font-family:var(--mono); font-size:9.5px; font-weight:600;\n    letter-spacing:.06em; color:var(--clay);}\n.pc .gate__t{font-family:var(--mono); font-size:10.5px; letter-spacing:.04em; color:var(--muted); line-height:1.4;}\n@media(max-width:760px){.pc .gates{flex-direction:column;}\n.pc .gph{width:100%;}\n.pc .gate{flex-basis:auto; flex-direction:row; padding:10px 0; gap:12px;}\n}\n.pc .mocks{display:grid; grid-template-columns:1fr 1fr; gap:20px; margin-top:22px;}\n@media(max-width:760px){.pc .mocks{grid-template-columns:1fr;}\n}\n.pc .mock{border:1px solid var(--rule); border-radius:12px; background:var(--card); overflow:hidden;}\n.pc .mock__bar{display:flex; align-items:center; gap:6px; padding:9px 13px; background:var(--paper-2);\n    border-bottom:1px solid var(--rule);}\n.pc .mock__bar i{width:9px; height:9px; border-radius:50%; background:#D8CEBC; display:block;}\n.pc .mock__ttl{font-family:var(--mono); font-size:11px; letter-spacing:.06em; text-transform:uppercase;\n    color:var(--muted); margin-left:6px;}\n.pc .mock__body{padding:16px 18px 18px;}\n.pc .kv{display:flex; justify-content:space-between; gap:12px; font-size:13.5px; padding:7px 0;\n    border-top:1px solid var(--rule); color:var(--ink-soft);}\n.pc .kv:first-child{border-top:0;}\n.pc .kv b{font-family:var(--mono); font-size:11px; letter-spacing:.04em; text-transform:uppercase; color:var(--muted); font-weight:500;}\n.pc .pill{font-family:var(--mono); font-size:10px; padding:2px 8px; border-radius:20px; border:1px solid var(--rule); color:var(--muted);}\n.pc .pill.ok{background:#E7F0EA; color:var(--green); border-color:#CFE2D6;}\n.pc .pill.warn{background:#FBEEDD; color:#B07A2E; border-color:#EDD8B6;}\n.pc .pill.hot{background:#FBEAE4; color:#B0402C; border-color:#EFCabe;}\n.pc .rank{display:flex; align-items:flex-start; gap:10px; font-size:13.5px; padding:8px 0; border-top:1px solid var(--rule); line-height:1.4;}\n.pc .rank:first-of-type{border-top:0;}\n.pc .rank .r{font-family:var(--mono); font-size:12px; color:var(--clay); font-weight:600; flex:0 0 auto;}\n.pc .mockcap{font-family:var(--mono); font-size:12px; color:var(--muted); margin-top:12px; line-height:1.5;}\n.pc .mockcap b{color:var(--ink); font-weight:500;}\n.pc .calls{border-top:1px solid var(--rule); margin-top:8px;}\n.pc .call{display:grid; grid-template-columns:200px 1fr; gap:40px; padding:34px 0; border-bottom:1px solid var(--rule);}\n.pc .call__k{font-family:var(--mono); font-size:12px; font-weight:500; letter-spacing:.12em;\n    text-transform:uppercase; color:var(--clay); line-height:1.5; padding-top:5px; white-space:pre-line;}\n.pc .call__b{max-width:60ch;}\n.pc .call__b p:last-child{margin-bottom:0;}\n.pc .call__b p{font-size:16px;}\n@media(max-width:720px){.pc .call{grid-template-columns:1fr; gap:10px; padding:28px 0;}\n.pc .call__k{padding-top:0;}\n}\n.pc .cast{display:grid; grid-template-columns:repeat(3,1fr); gap:16px; margin-top:36px;}\n@media(max-width:820px){.pc .cast{grid-template-columns:repeat(2,1fr);}\n}\n@media(max-width:520px){.pc .cast{grid-template-columns:1fr;}\n}\n.pc .group{border:1px solid var(--rule); border-radius:12px; background:var(--card);\n    border-top:3px solid var(--gc,#999); padding:16px 18px 18px;}\n.pc .group__h{font-family:var(--mono); font-size:11.5px; font-weight:600; letter-spacing:.11em;\n    text-transform:uppercase; color:var(--gc,#777); margin-bottom:8px;}\n.pc .agent{display:flex; align-items:center; gap:12px; padding:9px 0; border-top:1px solid var(--rule);}\n.pc .agent:nth-of-type(2){border-top:0;}\n.pc .agent .sp{flex:0 0 auto; align-self:center;}\n.pc .agent__n{flex:1; font-size:15px; color:var(--ink); line-height:1.25;}\n.pc .agent__n small{display:block; font-size:12px; color:var(--muted); margin-top:2px; line-height:1.35;}\n.pc .tier{font-family:var(--mono); font-size:10px; font-weight:500; letter-spacing:.05em;\n    text-transform:uppercase; padding:2px 7px; border-radius:20px; white-space:nowrap;\n    border:1px solid var(--rule); color:var(--muted); flex:0 0 auto; align-self:center;}\n.pc .tier.opus{background:#F6E8E2; color:#9C4A32; border-color:#EAD3C8;}\n.pc .tier.sonnet{background:#E7F0EA; color:#2E7D57; border-color:#CFE2D6;}\n.pc .tier.haiku{background:#EEF0F3; color:#4E6E8E; border-color:#DBE1E8;}\n.pc .g-prod{--gc:var(--clay);}\n.pc .g-rev{--gc:var(--green);}\n.pc .g-adv{--gc:var(--red);}\n.pc .g-res{--gc:var(--steel);}\n.pc .g-ops{--gc:var(--amber);}\n.pc .g-con{--gc:var(--plum);}\n.pc .ledger{display:grid; grid-template-columns:1fr 1fr; gap:20px; margin-top:34px;}\n@media(max-width:680px){.pc .ledger{grid-template-columns:1fr;}\n}\n.pc .col{border:1px solid #2b2d38; border-radius:12px; padding:22px 24px; background:var(--dark-2);}\n.pc .col.can{border-left:3px solid var(--grn);}\n.pc .col.cant{border-left:3px solid var(--amber);}\n.pc .col h3{font-family:var(--mono); font-size:12px; font-weight:600; letter-spacing:.09em;\n    text-transform:uppercase; margin-bottom:12px;}\n.pc .col.can h3{color:var(--grn);}\n.pc .col.cant h3{color:var(--amber);}\n.pc .col ul{list-style:none; margin:0; padding:0;}\n.pc .col li{font-size:14.5px; line-height:1.45; padding:9px 0 9px 20px; position:relative; color:#CFCBD6;}\n.pc .col li+li{border-top:1px solid #262833;}\n.pc .col.can li::before{content:\"+\"; position:absolute; left:0; color:var(--grn); font-weight:700;}\n.pc .col.cant li::before{content:\"–\"; position:absolute; left:0; color:var(--amber); font-weight:700;}\n.pc .honest{margin-top:20px; border:1px solid #2b2d38; border-left:3px solid var(--amber);\n    border-radius:10px; padding:18px 20px; font-family:var(--mono); font-size:12.5px;\n    color:var(--dark-mut); line-height:1.6;}\n.pc .honest b{color:var(--amber); font-weight:600;}\n.pc .seam{background:var(--paper-2); border-top:1px solid var(--rule); border-bottom:1px solid var(--rule);}\n.pc .seam ul{list-style:none; margin:18px 0 0; padding:0;}\n.pc .seam li{font-size:16px; color:var(--ink-soft); padding:8px 0 8px 22px; position:relative; line-height:1.45;}\n.pc .seam li::before{content:\"→\"; position:absolute; left:0; color:var(--clay);}\n.pc .tag-soon{font-family:var(--mono); font-size:10px; letter-spacing:.05em; text-transform:uppercase;\n    color:var(--muted); border:1px solid var(--rule); border-radius:20px; padding:1px 7px; margin-left:8px;}\n.pc .foot{padding:60px 0 84px;}\n.pc .foot a.mail{font-family:var(--serif); font-size:26px; font-weight:600; color:var(--ink);\n    text-decoration:none; border-bottom:2px solid var(--clay);}\n.pc .foot a.mail:hover{color:var(--clay);}\n.pc .foot .meta{font-family:var(--mono); font-size:13px; color:var(--muted); line-height:1.9; margin-top:22px;}\n.pc .foot .meta b{color:var(--ink); font-weight:500;}\n.pc a:focus-visible, .pc .crumb:focus-visible{outline:2px solid var(--clay); outline-offset:3px; border-radius:2px;}\n.pc .rise{opacity:0; transform:translateY(14px); transition:opacity .6s ease, transform .6s ease;}\n.pc .rise.in{opacity:1; transform:none;}\n@media(prefers-reduced-motion:reduce){.pc{scroll-behavior:auto;}\n.pc .rise{opacity:1; transform:none; transition:none;}\n}";

